"""Self-contained, script-free report with escaped local metadata."""
import html
import json


def escape(value):
    return html.escape(str(value), quote=True)


def text_report(report):
    lines = [f"BackupScope: {len(report['findings'])} gaps, {len(report['unknowns'])} unknowns, {len(report['rows'])} mounts.", report["scope"]]
    for row in report["rows"]:
        lines.append(f"{row['status'].upper():10} {row['resource']} -> {row['snapshot_path'] or '—'}")
    for item in report["findings"] + report["unknowns"]:
        lines.append(f"{item['code']} {item.get('resource', 'snapshot')}: {item['message']}")
    # Escape terminal controls if a library caller supplied unvalidated metadata.
    return "\n".join("".join(c if ord(c) >= 32 or c == '\n' else repr(c)[1:-1] for c in line) for line in lines) + "\n"


def html_report(report):
    code = report["exit_code"]
    title = "Evidence needs attention" if code else "Path-presence requirements met"
    tone = "incomplete" if code == 2 else "gap" if code else "observed"
    diagnostics = "".join(f'<article class="diagnostic"><b>{escape(i["code"])}</b><div><strong>{escape(i.get("resource", "Snapshot / inventory"))}</strong><p>{escape(i["message"])}</p></div></article>' for i in report["findings"] + report["unknowns"])
    rows = []
    for row in report["rows"]:
        owners = "".join(f'<li>{escape(o["container"])} <span>→ {escape(o["destination"])} · {"read only" if o["read_only"] else "writable"}</span></li>' for o in row["owners"])
        rows.append(f'<tr><td><span class="badge {escape(row["status"])}">{escape(row["status"])}</span></td><td><strong>{escape(row["resource"])}</strong><ul>{owners}</ul></td><td><code>{escape(row["snapshot_path"] or "—")}</code><small>{escape(row["detail"])}</small></td><td>{row["files"]:,}<small>{row["bytes"]:,} bytes</small></td></tr>')
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>BackupScope — snapshot coverage</title><style>
:root{color-scheme:light;--ink:#172b3a;--muted:#60717e;--line:#dde5e9;--green:#146a54;--rust:#aa482e}*{box-sizing:border-box}body{margin:0;font:15px/1.6 system-ui,sans-serif;color:var(--ink);background:#f3f6f7}header{background:#142b39;color:white;padding:22px max(24px,calc((100vw - 1180px)/2));display:flex;align-items:center;justify-content:space-between;gap:20px}header b{font-size:24px;letter-spacing:-1px}header span{font-size:12px;color:#bbd0db}main{max-width:1228px;margin:auto;padding:42px 24px}h1{font-size:clamp(29px,4vw,44px);line-height:1.15;letter-spacing:-1.5px;margin:9px 0 15px}h2{font-size:19px;margin:0 0 16px}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--muted)}.lead{max-width:800px;color:var(--muted);margin:0 0 28px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:30px}.stat,section{border:1px solid var(--line);background:white;border-radius:12px}.stat{padding:18px 24px}.stat b{display:block;font-size:34px;font-weight:600}.stat span{color:var(--muted);font-size:13px}section{padding:24px;margin:22px 0}.diagnostic{display:flex;gap:18px;padding:18px 0;border-top:1px solid var(--line)}.diagnostic b{color:var(--rust);font:12px/1.5 ui-monospace,monospace;padding-top:4px}.diagnostic div{min-width:0;overflow-wrap:anywhere}.diagnostic p{margin:5px 0 0;color:var(--muted);font-size:14px}table{width:100%;border-collapse:collapse;text-align:left}th{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:var(--muted);padding:0 12px 15px}td{padding:20px 12px;vertical-align:top;border-top:1px solid var(--line);font-size:13px;overflow-wrap:anywhere}td strong{font-family:ui-monospace,monospace;font-size:12px}ul{padding:0;list-style:none;margin:9px 0 0}li{font-size:12px}li span,small{color:var(--muted)}small{display:block;margin-top:8px;font-size:12px;line-height:1.6}code{font:12px/1.7 ui-monospace,monospace;overflow-wrap:anywhere}.badge{white-space:nowrap;display:inline-block;padding:4px 9px;border-radius:5px;text-transform:uppercase;letter-spacing:.5px;font-size:10px;font-weight:700;background:#edf1f3}.missing,.failed,.gap{color:#984026;background:#fdf0e8}.unknown,.incomplete{color:#805719;background:#fcf3df}.observed{color:#146a54;background:#e8f5ef}.banner{padding:14px 18px;border-radius:8px;margin:20px 0}.meta{display:grid;grid-template-columns:1fr 1fr;gap:15px}.meta p{margin:0;font-size:12px;color:var(--muted)}.meta code{display:block;color:var(--ink)}footer{font-size:12px;color:var(--muted);padding:10px 0 25px}details{margin-top:16px}summary{cursor:pointer;font-weight:600;font-size:13px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.6 ui-monospace,monospace;background:#f5f7f8;padding:18px;border-radius:6px}summary:focus-visible,.table-wrap:focus-visible{outline:3px solid #146a54;outline-offset:4px}@media(max-width:760px){main{padding:28px 16px}header{padding:18px 16px}.stats{gap:8px}.stat{padding:12px}.stat b{font-size:28px}.stat span{display:block;min-height:42px}section{padding:18px}.table-wrap{overflow-x:auto}table{min-width:680px}.meta{grid-template-columns:1fr}header span{max-width:145px;text-align:right}}@media print{body{background:white}header{background:white;color:black}section{break-inside:avoid}.table-wrap{overflow:visible}table{min-width:0}details{display:none}}
</style></head><body><header><b>BackupScope<span> / 0.1</span></b><span>LOCAL EVIDENCE · NO DATA UPLOAD</span></header><main>''' + f'''
<div class="eyebrow">Docker mounts × restic snapshot</div><h1>{title}</h1><p class="lead">A successful backup job can still leave a new volume behind. This report compares the supplied mount inventory with paths in one selected snapshot.</p>
<div class="stats"><div class="stat"><span>Persistent & other mounts</span><b>{len(report['rows'])}</b></div><div class="stat"><span>Gaps / policy failures</span><b>{len(report['findings'])}</b></div><div class="stat"><span>Unknowns</span><b>{len(report['unknowns'])}</b></div></div>
<div class="banner {tone}">{escape(report['scope'])}</div>
<section><h2>What needs review</h2>{diagnostics or '<p>No path-presence violations found. Continue with repository integrity checks and a real restore drill.</p>'}</section>
<section><h2>Mount coverage</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Mount coverage table; scroll horizontally on small screens"><table><thead><tr><th>Status</th><th>Resource / consumers</th><th>Snapshot evidence</th><th>Regular files</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div></section>
<section><h2>Evidence identity</h2><div class="meta"><p>HOST<code>{escape(report['snapshot']['hostname'])}</code></p><p>CHECKED AT<code>{escape(report['checked_at'])}</code></p><p>SNAPSHOT ID<code>{escape(report['snapshot']['id'])}</code></p><p>SNAPSHOT / INVENTORY AGE<code>{report['snapshot_age_hours']} h / {report['inventory_age_hours']} h</code></p></div><details><summary>Portable JSON report</summary><pre>{escape(json.dumps(report,ensure_ascii=False,indent=2))}</pre></details></section><footer>BackupScope · MIT · Only supplied inputs are considered. Excluded mounts remain visible. Paths and host identities may be sensitive; review before sharing.</footer></main></body></html>'''
